/* For-ADM: dyls targeted JS cache v1. */
(function(){
var target=/^\/assets\/(?:index|helperService|NewAds|home|explorer|Main|search|playerService|player)-[A-Za-z0-9_-]+\.js$/;
function known(url){try{var u=new URL(url,self.location.origin);return u.origin===self.location.origin&&target.test(u.pathname)}catch(e){return false}}
self.addEventListener('activate',function(event){event.waitUntil(caches.keys().then(function(names){return Promise.all(names.map(function(name){return caches.open(name).then(function(cache){return cache.keys().then(function(keys){return Promise.all(keys.filter(function(key){return known(key.url)}).map(function(key){return cache.delete(key)}))})})}))}).catch(function(){}))});
self.addEventListener('fetch',function(event){if(event.request.method!=='GET'||!known(event.request.url))return;event.stopImmediatePropagation();event.respondWith((async function(){try{var response=await fetch(event.request,{cache:'no-cache'});if(!response.ok)throw Error('Dyls module response '+response.status);if(/javascript|ecmascript/i.test(response.headers.get('content-type')||'')){try{var cache=await caches.open('for-adm-dyls-js-v1');await cache.put(event.request,response.clone())}catch(e){}}return response}catch(error){var cached=await caches.match(event.request);if(cached)return cached;throw error}})())});
})();
